import duckdb
con=duckdb.connect(); q=lambda s: con.execute(s).fetchall()
T=lambda t: f"read_parquet('dl/t/{t}.parquet')"
rc=T("roll_call_votes")
print("RCV vote_id == congress-chamber-session-roll:", q(f"select count(*), count(*) filter (where vote_id = congress||'-'||chamber||'-'||session||'-'||roll_number) from {rc}"))
print("RCV chamber values:", q(f"select chamber, min(cast(congress as int)), max(cast(congress as int)), count(*) from {rc} group by 1"))
print("RCV documents type values:", q(f"select d.type, count(*) from (select unnest(documents) d from {rc}) group by 1 order by 2 desc limit 8"))
print("RCV documents PN sample:", q(f"select d.type, d.name, d.number, d.congress from (select unnest(documents) d from {rc}) where d.type ilike '%PN%' or d.name ilike 'PN%' or d.number ilike 'PN%' limit 5"))
print("RCV docs: struct congress null share:", q(f"select count(*), count(*) filter (where d.congress is null) from (select unnest(documents) d from {rc})"))
print("RCV senate votes with PN doc: nominations with >1 vote:", q(f"""
 with x as (select r.congress, d.number as pn, r.vote_id from (select congress, vote_id, unnest(documents) d from {rc} where chamber='senate') r where d.type ilike '%nomination%' or d.name ilike 'PN%' or d.number ilike 'PN%')
 select count(distinct (congress,pn)) total, count(distinct (congress,pn)) filter (where c>1) multi from (select congress,pn,count(distinct vote_id) c from x group by 1,2)"""))
print("RCV bill_id sample:", q(f"select bill_id from {rc} where bill_id is not null limit 3"))
print("RCV vote_day sample:", q(f"select vote_day, vote_date from {rc} limit 2"))
n=T("nominations")
print("NOM congress values:", q(f"select congress, count(*) from {n} group by 1 order by 1"))
print("NOM citation/number/part sample:", q(f"select citation, number, part_number from {n} where part_number is not null and part_number<>'' limit 3"), q(f"select citation, number, part_number from {n} limit 2"))
c=T("committees")
print("COM chamber values:", q(f"select chamber, count(*) from {c} group by 1"))
print("COM system_code samples:", q(f"select system_code from {c} where system_code in ('hsag03','hlig00','hsag00','jsec00','ssju00') "))
print("COM system_code pattern:", q(f"select count(*), count(*) filter (where regexp_matches(system_code,'^[hjs][a-z]{{3}}[0-9]{{2}}$')) from {c}"))
print("COM history startDate sample:", q(f"select h.officialName, h.startDate, h.endDate from (select unnest(history) h from {c}) limit 2"))
print("COM is_current counts:", q(f"select is_current, count(*) from {c} group by 1"))
a=T("committee_assignments")
print("ASSIGN congress values:", q(f"select congress, chamber, count(*) from {a} group by 1,2 order by 1,2"))
print("ASSIGN rank numeric?:", q(f"select count(*), count(*) filter (where regexp_matches(rank,'^[0-9]+$')) from {a}"), q(f"select position, count(*) from {a} group by 1 order by 2 desc limit 5"))
b=T("congress_bills")
print("BILLS bill_id pattern:", q(f"select count(*), count(*) filter (where regexp_matches(bill_id,'^[0-9]+-[a-z]+-[0-9]+$')) from {b}"), q(f"select bill_id from {b} limit 2"), q(f"select min(cast(congress as int)) from {b}"))
print("BILLS bill_type values:", q(f"select bill_type, count(*) from {b} group by 1 order by 2 desc"))
print("BILLS stage values:", q(f"select stage, count(*) from {b} group by 1 order by 2 desc limit 8"))
mt=T("member_terms"); print("TERMS term_type:", q(f"select term_type, count(*) from {mt} group by 1"))
print("MEMBERS rows:", q(f"select count(*), min(first_term_start) from {T('members')}"))
cbo=T("cbo_cost_estimates"); print("CBO bill_id pattern:", q(f"select count(*), count(*) filter (where regexp_matches(bill_id,'^[0-9]+-[a-z]+-[0-9]+$')) from {cbo}"))
bvr=T("bill_vote_references"); print("BVR chamber values:", q(f"select chamber, count(*) from {bvr} group by 1"))
print("BVR -> RCV join by composed vote_id:", q(f"select count(*), count(*) filter (where exists (select 1 from {rc} r where r.vote_id = v.congress||'-'||v.chamber||'-'||v.session||'-'||v.roll_number)) from {bvr} v"))
